t as materialized (
 select r.id, r.item, r.detail, r.filters, (md5(to_jsonb(r)::text) = '87d760610c8c829e0ea5a8a41dc61d79') as unchanged
 from public.corpus_records r where r.dataset = 'judge_cross_profiles' and r.id = 'summary:overview'),
y as (
 select t.*, jsonb_set(t.item, '{summary,scatter}',
   (select coalesce(jsonb_agg(case when v.nid is not null and (s->>'judge_profile_id') is null
                                   then s || jsonb_build_object('judge_profile_id', v.profile, 'photo', coalesce(v.photo, s->>'photo')) else s end order by o), '[]'::jsonb)
      from jsonb_array_elements(t.item->'summary'->'scatter') with ordinality q(s, o) left join v on v.nid = s->>'nid')) as new_item
 from t),
ins as (
 insert into corpus_ingest.cleanup_decisions (dataset, record_id, issue, disposition, reason, evidence, original_record, replacement, run_id)
 select 'judge_cross_profiles', y.id, 'dejudges20261027_judge_cross_profile_fill', 'label_override', 'Summary scatter: judge_profile_id / photo filled for the same judges.',
  jsonb_build_object('contract', 'judge-cross-profiles-relink/2026-10-27.v1', 'entries', (select count(*) from v)),
  jsonb_build_object('id', y.id, 'item', y.item, 'detail', y.detail, 'filters', y.filters, 'row_md5', '87d760610c8c829e0ea5a8a41dc61d79'),
  jsonb_build_object('item', y.new_item, 'detail', y.detail, 'filters', y.filters),
  'f6bae0b3-2657-5f85-9604-1cb6e9815ef2'::uuid
 from y where y.unchanged
 on conflict (dataset, record_id, issue) do nothing
 returning record_id)
select (select count(*) from t where unchanged) as summary_unchanged, (select count(*) from ins) as audit_rows_written;

-- ===== statement 3: apply (judge records and summary) from the audited before-images =====
with u as (
 update public.corpus_records r
    set item = c.replacement->'item', detail = c.replacement->'detail', filters = c.replacement->'filters'
   from corpus_ingest.cleanup_decisions c
  where c.dataset = 'judge_cross_profiles' and c.issue = 'dejudges20261027_judge_cross_profile_fill' and c.run_id = 'f6bae0b3-2657-5f85-9604-1cb6e9815ef2'::uuid
    and r.dataset = 'judge_cross_profiles' and r.id = c.record_id and md5(to_jsonb(r)::text) = c.original_record->>'row_md5'
 returning r.id)
select count(*) as updated from u;

-- ===== verification (read-only) =====
-- V1 expected after apply: judges = 420, with_profile_filter = 420, without_profile = 0
select count(*) filter (where item->>'kind' = 'judge') as judges,
       count(*) filter (where item->>'kind' = 'judge' and jsonb_array_length(coalesce(filters->'judge_profile', '[]'::jsonb)) = 1) as with_profile_filter,
       count(*) filter (where item->>'kind' = 'judge' and item->'cross'->>'judge_profile_id' is null) as without_profile
from public.corpus_records where dataset = 'judge_cross_profiles';
-- V2 consistency (expected 0 rows): cross.judge_profile_id, filters.judge_profile and the leading Judge profile link agree
select id from public.corpus_records where dataset = 'judge_cross_profiles' and item->>'kind' = 'judge' and (
  (item->'cross'->>'judge_profile_id') is distinct from (filters->'judge_profile'->>0)
  or (item->'cross'->>'judge_profile_id' is not null and (item->'links'->0->>'url') is distinct from '/judges/' || (item->'cross'->>'judge_profile_id')));
-- V3 one judge_cross_profiles record per profile (expected 0 rows) and every profile exists in judges (expected 0 rows)
select filters->'judge_profile'->>0 as profile, count(*) from public.corpus_records where dataset = 'judge_cross_profiles' and filters ? 'judge_profile' and jsonb_array_length(filters->'judge_profile') = 1 group by 1 having count(*) > 1;
select c.id from public.corpus_records c where c.dataset = 'judge_cross_profiles' and c.filters->'judge_profile'->>0 is not null
   and not exists (select 1 from public.corpus_records j where j.dataset = 'judges' and j.id = c.filters->'judge_profile'->>0);
-- V4 the page lookup now finds a filled judge (expected 1 row)
select id, title from public.corpus_records where dataset = 'judge_cross_profiles' and filters @> '{"judge_profile":["e4437387cd29181d4dabb6874f4ed7f0"]}';
-- V5 audit rows of this contract (expected 238 judge rows + 1 summary row)
select count(*) from corpus_ingest.cleanup_decisions where issue = 'dejudges20261027_judge_cross_profile_fill' and run_id = 'f6bae0b3-2657-5f85-9604-1cb6e9815ef2'::uuid;
